CREATE OR REPLACE FUNCTION public.can_manage_company(_company text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT coalesce(auth.jwt()->>'aal' = 'aal2', false) AND (public.has_role(auth.uid(), 'super_admin') OR (public.has_role(auth.uid(), 'admin') AND _company IS NOT NULL AND _company = public.get_user_company_slug(auth.uid()))) $$;
REVOKE ALL ON FUNCTION public.can_manage_company(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_manage_company(text) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.protect_profile_membership() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.role() = 'authenticated' THEN IF TG_OP = 'INSERT' THEN RAISE EXCEPTION 'Profiles must be created through account registration'; END IF; IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.id IS DISTINCT FROM OLD.id OR NEW.company_slug IS DISTINCT FROM OLD.company_slug OR NEW.company_name IS DISTINCT FROM OLD.company_name THEN RAISE EXCEPTION 'Company membership cannot be changed through profile editing'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.protect_profile_membership() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER protect_profile_membership BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_membership();
ALTER POLICY "Admins can view all profiles" ON public.profiles USING (public.has_role(auth.uid(), 'admin') AND public.can_manage_company(company_slug));
ALTER POLICY "Super admins can view all profiles" ON public.profiles USING (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(company_slug));
ALTER POLICY "Admins read companies" ON public.companies USING (public.has_role(auth.uid(), 'admin') AND public.can_manage_company(slug));
ALTER POLICY "Super admins manage companies" ON public.companies USING (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(slug)) WITH CHECK (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(slug));
ALTER POLICY "Admins can view all roles" ON public.user_roles USING (public.can_manage_company(public.get_user_company_slug(user_id)));
ALTER POLICY "Admins can insert non-super roles" ON public.user_roles WITH CHECK (public.has_role(auth.uid(), 'admin') AND role <> 'super_admin' AND public.can_manage_company(public.get_user_company_slug(user_id)) AND NOT public.has_role(user_id, 'super_admin'));
ALTER POLICY "Admins can update non-super roles" ON public.user_roles USING (public.has_role(auth.uid(), 'admin') AND role <> 'super_admin' AND public.can_manage_company(public.get_user_company_slug(user_id)) AND NOT public.has_role(user_id, 'super_admin')) WITH CHECK (public.has_role(auth.uid(), 'admin') AND role <> 'super_admin' AND public.can_manage_company(public.get_user_company_slug(user_id)) AND NOT public.has_role(user_id, 'super_admin'));
ALTER POLICY "Admins can delete non-super roles" ON public.user_roles USING (public.has_role(auth.uid(), 'admin') AND role <> 'super_admin' AND public.can_manage_company(public.get_user_company_slug(user_id)) AND NOT public.has_role(user_id, 'super_admin'));
ALTER POLICY "Super admins can insert roles" ON public.user_roles WITH CHECK (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(public.get_user_company_slug(user_id)));
ALTER POLICY "Super admins can update roles" ON public.user_roles USING (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(public.get_user_company_slug(user_id))) WITH CHECK (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(public.get_user_company_slug(user_id)));
ALTER POLICY "Super admins can delete roles" ON public.user_roles USING (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(public.get_user_company_slug(user_id)));
ALTER POLICY "Admins can insert role permissions" ON public.role_permissions WITH CHECK (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(NULL));
ALTER POLICY "Admins can update role permissions" ON public.role_permissions USING (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(NULL)) WITH CHECK (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(NULL));
ALTER POLICY "Admins can delete role permissions" ON public.role_permissions USING (public.has_role(auth.uid(), 'super_admin') AND public.can_manage_company(NULL));